mapper.insert:
INSERT
	FILE_MASTER (
		DOMAIN_ID
		, COMPANY_CD
		, TASK_ID
	    , PROJECT_ID
		, FILE_NM
		, FILE_DISP_NM
		, UPDATE_USR
		, UPDATE_DT
		, CREATE_USR
		, CREATE_DT
	)
	VALUES (
		#{domainId}
		, #{companyCd}
		, #{taskId}
		, #{projectId}
		, #{fileNm}
		, #{fileDispNm}
		, #{createUsr}
		, NOW()
		, #{createUsr}
		, NOW()
	)

mapper.delete:
DELETE FROM
	FILE_MASTER
WHERE
	DOMAIN_ID = #{domainId}
	AND TASK_ID = #{taskId}

mapper.select:
SELECT fm.DOMAIN_ID , fm.COMPANY_CD , fm.FILE_ID , fm.TASK_ID , tm.TASK_NM , tm.TASK_TYPE_CD , SF_GET_CODE_NM('ko-KR', 'CM007', tm.TASK_TYPE_CD, tm.COMPANY_CD, tm.DOMAIN_ID) AS TASK_TYPE_NM , fm.PROJECT_ID , fm.FILE_NM , fm.FILE_DISP_NM , fm.UPDATE_USR , CONVERT_TZ(fm.UPDATE_DT, '+00:00', '+09:00') AS UPDATE_DT , fm.CREATE_USR , CONVERT_TZ(fm.CREATE_DT, '+00:00', '+09:00') AS CREATE_DT FROM file_master fm INNER JOIN task_master tm ON (fm.TASK_ID = tm.TASK_ID AND (tm.DEL_YN = 'N' OR tm.DEL_YN IS NULL)) WHERE fm.project_id = #{projectId}
AND fm.FILE_DISP_NM LIKE CONCAT('%', #{fileDispNm}, '%')
ORDER BY fm.CREATE_DT , tm.TASK_NM
LIMIT #{start}, #{length}
